package com.turboio.addon;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.media.*;import android.os.*;import org.json.*;import java.util.*;import java.net.*;
final class CloudCaption {
 static final String ENDPOINT="",MODEL="qwen3.8-livetranslate-flash-realtime";
 private static final java.util.concurrent.atomic.AtomicInteger queuedEvents=new java.util.concurrent.atomic.AtomicInteger();private static Context app;private static BoundedWebSocket ws;private static volatile AudioRecord recorder;private static volatile long epoch;private static CaptionText parser;private static AudioManager audio;private static int previousMode;private static AudioFocusRequest focus;private static boolean routed,show,translation,worker;private static String target;static String note="未开始收音",source="",translated="";static boolean active,ready;
 static void init(Context c){app=c.getApplicationContext();audio=(AudioManager)app.getSystemService(Context.AUDIO_SERVICE);BackgroundWork.register("字幕",()->stop("从后台通知停止"));}
 static List<AudioDeviceInfo> inputs(){List<AudioDeviceInfo> a=new ArrayList<>();try{for(AudioDeviceInfo d:audio.getDevices(AudioManager.GET_DEVICES_INPUTS))if(d.getType()==AudioDeviceInfo.TYPE_BUILTIN_MIC||d.getType()==AudioDeviceInfo.TYPE_BLUETOOTH_SCO||Build.VERSION.SDK_INT>=31&&d.getType()==AudioDeviceInfo.TYPE_BLE_HEADSET||d.getType()==AudioDeviceInfo.TYPE_USB_HEADSET||d.getType()==AudioDeviceInfo.TYPE_WIRED_HEADSET)a.add(d);}catch(SecurityException e){note="请在系统设置授权麦克风与附近设备，然后重新进入此页";}return a;}
 static void start(Activity a,AudioDeviceInfo input,boolean display,boolean translate,String language){if(active)return;if(a.checkSelfPermission("android.permission.RECORD_AUDIO")!=PackageManager.PERMISSION_GRANTED){a.requestPermissions(new String[]{"android.permission.RECORD_AUDIO"},7622);note="请授权麦克风后再次点击开始";return;}if(input==null){note="请选择系统实际提供的输入";return;}if(Build.VERSION.SDK_INT>=31&&(input.getType()==AudioDeviceInfo.TYPE_BLUETOOTH_SCO||input.getType()==AudioDeviceInfo.TYPE_BLE_HEADSET)&&a.checkSelfPermission("android.permission.BLUETOOTH_CONNECT")!=PackageManager.PERMISSION_GRANTED){a.requestPermissions(new String[]{"android.permission.BLUETOOTH_CONNECT"},7623);note="请授权附近设备后再次开始";return;}if(NativeTransfer.busy()||MusicBridge.active()||ReaderBridge.active()||NativeNavigation.active()||NavGlasses.active()){note="请结束其他眼镜显示或传输任务";return;}
  try{String key=SecretStore.get(a,"caption_key");if(key.isEmpty()){note="请先配置云端字幕 Key";return;}android.content.SharedPreferences p=app.getSharedPreferences("turboio_captions",0);URI u=new URI(p.getString("url",ENDPOINT));if(!"wss".equals(u.getScheme())||u.getQuery()!=null||u.getFragment()!=null||u.getUserInfo()!=null)throw new IllegalArgumentException();String model=p.getString("model",MODEL);if(!model.matches("[a-zA-Z0-9._-]{1,128}"))throw new IllegalArgumentException();target=language;translation=translate;show=display;source=translated="";parser=new CaptionText();active=true;ready=false;long ticket=++epoch;note="连接云端，尚未开启麦克风";BackgroundWork.acquire("字幕",128|(display?16:0));ws=new BoundedWebSocket(new BoundedWebSocket.Listener(){public void opened(){}public void closed(String code){NativeTransfer.MAIN.post(()->{if(epoch==ticket&&active)stop("字幕连接结束："+code);});}public void text(String s){if(queuedEvents.incrementAndGet()>32){queuedEvents.decrementAndGet();BoundedWebSocket socket=ws;if(socket!=null)socket.close();return;}NativeTransfer.MAIN.post(()->{try{if(epoch!=ticket||!active)return;try{event(new JSONObject(s),input,ticket);}catch(Exception e){stop("字幕事件格式不兼容，已停止收音");}}finally{queuedEvents.decrementAndGet();}});}});ws.connect(u.toString()+"?model="+URLEncoder.encode(model,"UTF-8"),key);NativeTransfer.MAIN.postDelayed(()->{if(epoch==ticket&&!ready)stop("云端会话配置超时");},15000);
  }catch(Exception e){stop("配置格式错误或加密存储不可用");}}
 private static void event(JSONObject e,AudioDeviceInfo input,long ticket)throws Exception{String type=e.optString("type");if(type.equals("session.created")){ws.send(new JSONObject().put("type","session.update").put("session",new JSONObject().put("output_modalities",new JSONArray().put("text")).put("translation",new JSONObject().put("language",target))).toString());return;}if(type.equals("session.updated")){if(ready)return;JSONObject session=e.getJSONObject("session"),f=session.getJSONObject("audio").getJSONObject("input").getJSONObject("format");JSONArray mods=session.getJSONArray("output_modalities");if(mods.length()!=1||!mods.getString(0).equals("text")||!f.getString("type").equals("pcm")||f.getInt("sample_rate")!=16000)throw new Exception();ready=true;capture(input,ticket);return;}if(type.equals("error")||type.equals("session.finished")){stop("云端结束或拒绝会话；请检查权限和服务配置");return;}String value=e.has("delta")?e.optString("delta"):type.endsWith("completed")?e.optString("transcript"):e.optString("text");CaptionText.Update u=parser.accept(type,e.optString("event_id"),e.optString("item_id"),value,e.optInt("content_index",0));if(u!=null){if(u.channel.equals("source"))source=u.text;else translated=u.text;if(show)NavGlasses.offer(translation?(translated.isEmpty()?source:translated):source);}}
 private static void capture(AudioDeviceInfo input,long ticket)throws Exception{boolean bt=input.getType()==AudioDeviceInfo.TYPE_BLUETOOTH_SCO||Build.VERSION.SDK_INT>=31&&input.getType()==AudioDeviceInfo.TYPE_BLE_HEADSET;previousMode=audio.getMode();if(bt){if(Build.VERSION.SDK_INT<31)throw new IllegalStateException("Bluetooth mic requires Android12");AudioDeviceInfo selected=null;for(AudioDeviceInfo d:audio.getAvailableCommunicationDevices())if(d.getType()==input.getType()&&(d.getId()==input.getId()||!d.getAddress().isEmpty()&&d.getAddress().equals(input.getAddress()))){selected=d;break;}if(selected==null)throw new IllegalStateException("no communication route");audio.setMode(AudioManager.MODE_IN_COMMUNICATION);routed=true;if(!audio.setCommunicationDevice(selected))throw new IllegalStateException();}
  focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN_TRANSIENT).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_VOICE_COMMUNICATION).build()).setOnAudioFocusChangeListener(c->{if(c<0)NativeTransfer.MAIN.post(()->{if(epoch==ticket)stop("音频焦点被其他应用取得");});}).build();if(audio.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED)throw new IllegalStateException();VoiceSpeech.stop("开始云端字幕");int min=AudioRecord.getMinBufferSize(16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);if(min<0)throw new IllegalStateException();AudioRecord r=new AudioRecord.Builder().setAudioSource(bt?MediaRecorder.AudioSource.VOICE_COMMUNICATION:MediaRecorder.AudioSource.VOICE_RECOGNITION).setAudioFormat(new AudioFormat.Builder().setSampleRate(16000).setEncoding(AudioFormat.ENCODING_PCM_16BIT).setChannelMask(AudioFormat.CHANNEL_IN_MONO).build()).setBufferSizeInBytes(Math.max(min,12800)).build();recorder=r;if(r.getState()!=AudioRecord.STATE_INITIALIZED||!r.setPreferredDevice(input))throw new IllegalStateException();r.startRecording();if(show&&!NavGlasses.startCaption("正在收音…"))throw new IllegalStateException();note="收音中 · "+input.getProductName()+" · 音频仅发送所配置云端，不保存录音";
  worker=true;new Thread(()->{try{byte[] bytes=new byte[3200];long until=SystemClock.elapsedRealtime()+2500;while(epoch==ticket){int n=r.read(bytes,0,bytes.length,AudioRecord.READ_BLOCKING);if(n<=0||n%2!=0)throw new IllegalStateException();AudioDeviceInfo actual=r.getRoutedDevice();if(actual==null||actual.getId()!=input.getId()){if(SystemClock.elapsedRealtime()<until)continue;throw new IllegalStateException("route mismatch");}String data=android.util.Base64.encodeToString(bytes,0,n,android.util.Base64.NO_WRAP);BoundedWebSocket socket=ws;if(epoch!=ticket||socket==null)break;if(!socket.send(new JSONObject().put("type","input_audio_buffer.append").put("audio",data).toString()))break;}}catch(Exception e){NativeTransfer.MAIN.post(()->{if(epoch==ticket)stop("输入路由变化或收音失败；没有切换到其他麦克风");});}finally{r.release();}},"TurboIO-caption-mic").start();}
 static void stop(String reason){epoch++;active=ready=false;AudioRecord r=recorder;recorder=null;if(r!=null){try{r.stop();}catch(RuntimeException ignored){}if(!worker)r.release();}worker=false;BoundedWebSocket w=ws;ws=null;if(w!=null)w.close();if(show)NavGlasses.stop();show=false;if(focus!=null){audio.abandonAudioFocusRequest(focus);focus=null;}if(routed){if(Build.VERSION.SDK_INT>=31)audio.clearCommunicationDevice();audio.setMode(previousMode);routed=false;}BackgroundWork.release("字幕");note=reason;}
}
